package net.tfminecraft.archaeo.ownership;

import net.tfminecraft.archaeo.CharacterTestSupport;
import net.tfminecraft.archaeo.site.SiteRepository;
import net.tfminecraft.tlibs.character.*;
import net.tfminecraft.tlibs.character.estate.*;
import org.bukkit.plugin.ServicePriority;
import org.junit.*;
import org.mockbukkit.mockbukkit.*;
import java.io.IOException;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class SiteEstatesTest {
    Path root;ServerMock server;SiteRepository repository;SiteOwnership store;CharacterIdentity identity;EstateService estates;
    final UUID id=UUID.randomUUID(),death=UUID.randomUUID();
    final CharacterRef from=new CharacterRef(UUID.randomUUID(),UUID.randomUUID()),to=new CharacterRef(UUID.randomUUID(),UUID.randomUUID());
    EstateDecision decision(long revision,Recipient target){return new EstateDecision(death,from,Optional.of(Instant.EPOCH),Instant.EPOCH,Optional.of(to),Optional.empty(),Optional.empty(),Recipient.FROZEN,target,Recipient.FROZEN,Recipient.SENDER,revision);}
    void activate(EstateDecision decision){when(estates.decision(death)).thenReturn(Optional.of(decision));when(identity.info(from.characterId())).thenReturn(Optional.of(new CharacterInfo(from,"Testator",CharacterStatus.DEAD,null,Set.of(),0,null)));when(identity.deathId(from.characterId())).thenReturn(Optional.of(death));when(estates.stateOf(from.characterId())).thenReturn(Optional.of(EstateState.DECIDED));}
    Map<String,Object> raw(){var raw=new LinkedHashMap<String,Object>();raw.put("schema",2);raw.put("actors-version",1);raw.put("id",id.toString());raw.put("director",from.characterId().toString());raw.put("status","ESTABLISHED");raw.put("actor-refs",new LinkedHashMap<>(Map.of(from.characterId().toString(),CharacterActors.ref(from),to.characterId().toString(),CharacterActors.ref(to))));raw.put("excavators",List.of(from.characterId().toString(),to.characterId().toString()));raw.put("workers",Map.of(from.characterId().toString(),Map.of("role","director","blocks-removed",11),to.characterId().toString(),Map.of("role","excavator","blocks-removed",17)));raw.put("prospect",Map.of("samples",Map.of(from.characterId().toString(),List.of("1,2,3")),"confirmed",List.of(from.characterId().toString())));var unknown=new LinkedHashMap<String,Object>();unknown.put("null",null);unknown.put("binary",new byte[]{0,127,-1});raw.put("future",unknown);return raw;}
    @Before public void setup()throws Exception{
        server=CharacterTestSupport.mock();root=Files.createTempDirectory("archaeo-estates");var plugin=MockBukkit.createMockPlugin();
        server.getServicesManager().unregister(CharacterIdentity.class,server.getServicesManager().load(CharacterIdentity.class));identity=mock(CharacterIdentity.class);server.getServicesManager().register(CharacterIdentity.class,identity,plugin,ServicePriority.Highest);
        estates=mock(EstateService.class);server.getServicesManager().register(EstateService.class,estates,plugin,ServicePriority.Highest);
        SiteDocuments.write(root.resolve("sites/"+id+".yml"),SiteDocuments.text(raw()));store=new SiteOwnership(root);store.estateGuard=SiteEstates::guard;store.open();repository=mock(SiteRepository.class);when(repository.ownership()).thenReturn(store);activate(decision(1,Recipient.character(to)));
    }
    @After public void cleanup()throws Exception{MockBukkit.unmock();try(var files=Files.walk(root)){for(Path p:files.sorted(Comparator.reverseOrder()).toList())Files.delete(p);}}
    @Test public void directorOnlyTransferPreservesAllWorkersProgressNullBinaryAndCumulativeFrozenWaitingReceipts()throws Exception{
        var before=SiteDocuments.copy(store.documents().get(id+".yml"));var participant=new SiteEstates(repository);var first=(Outcome.Done)participant.settle(decision(1,Recipient.character(to)));assertEquals(List.of(id.toString()),first.movedIds());assertEquals(to,SiteOwnership.director(store.documents().get(id+".yml")));var after=SiteDocuments.copy(store.documents().get(id+".yml"));after.put("director",before.get("director"));assertTrue(SiteDocuments.same(before,after));
        assertEquals(first,participant.settle(decision(1,Recipient.character(to))));
        int revision=2;for(var recipient:List.of(Recipient.FROZEN,Recipient.WAITING)){var next=decision(revision++,recipient);activate(next);store.open();assertEquals(first,participant.settle(next));}
        assertEquals(Integer.valueOf(1),participant.describe(to.characterId()).counts().get("sites"));assertEquals(Integer.valueOf(0),participant.describe(from.characterId()).counts().get("sites"));
    }
    @Test public void everyEstateWriteCutRecoversExactlyOnceAndStalePartialDecisionBlocks()throws Exception{
        for(int cut=1;cut<=3;cut++){
            Path folder=root.resolve("cut"+cut);SiteDocuments.write(folder.resolve("sites/"+id+".yml"),SiteDocuments.text(raw()));store=new SiteOwnership(folder);store.estateGuard=SiteEstates::guard;store.open();when(repository.ownership()).thenReturn(store);activate(decision(1,Recipient.character(to)));int selected=cut;int[] count={0};
            try(var writes=mockStatic(SiteDocuments.class,CALLS_REAL_METHODS)){
                writes.when(()->SiteDocuments.write(any(Path.class),anyString())).thenAnswer(call->{call.callRealMethod();if(++count[0]==selected)throw new IOException("cut after estate publication");return null;});
                assertEquals(Outcome.Kind.RETRY,new SiteEstates(repository).settle(decision(1,Recipient.character(to))).kind());
            }
            if(cut!=2)assertEquals(Outcome.Kind.DONE,new SiteEstates(repository).settle(decision(1,Recipient.character(to))).kind());
            if(cut==2){activate(decision(2,Recipient.FROZEN));store.open();assertEquals(Outcome.Kind.BLOCKED,new SiteEstates(repository).settle(decision(2,Recipient.FROZEN)).kind());activate(decision(1,Recipient.character(to)));}
            store.open();assertEquals(to,SiteOwnership.director(store.documents().get(id+".yml")));assertEquals(List.of(id.toString()),((Outcome.Done)new SiteEstates(repository).settle(decision(1,Recipient.character(to)))).movedIds());assertEquals(1,store.files("ownership/journals").size());
        }
    }
    @Test public void realGuardRejectsRevivalRedeathWrongOwnerAndChangedRevisionBeforeMovement()throws Exception{
        var participant=new SiteEstates(repository);String original=store.before(id+".yml");when(identity.info(from.characterId())).thenReturn(Optional.of(new CharacterInfo(from,"Revived",CharacterStatus.ALIVE,null,Set.of(),0,null)));assertEquals(Outcome.Kind.RETRY,participant.settle(decision(1,Recipient.character(to))).kind());activate(decision(1,Recipient.character(to)));when(identity.deathId(from.characterId())).thenReturn(Optional.of(UUID.randomUUID()));assertEquals(Outcome.Kind.RETRY,participant.settle(decision(1,Recipient.character(to))).kind());activate(decision(1,Recipient.character(to)));when(identity.info(from.characterId())).thenReturn(Optional.of(new CharacterInfo(to,"Wrong account",CharacterStatus.DEAD,null,Set.of(),0,null)));assertEquals(Outcome.Kind.RETRY,participant.settle(decision(1,Recipient.character(to))).kind());activate(decision(2,Recipient.FROZEN));assertEquals(Outcome.Kind.RETRY,participant.settle(decision(1,Recipient.character(to))).kind());assertEquals(original,Files.readString(root.resolve("sites/"+id+".yml")));
    }
    @Test public void completedReceiptsRejectTamperingAndRestoredMovedSourcesAcrossRevisions()throws Exception{
        var participant=new SiteEstates(repository);assertEquals(Outcome.Kind.DONE,participant.settle(decision(1,Recipient.character(to))).kind());Path path=store.files("ownership/journals").getFirst();String receipt=Files.readString(path);var saved=SiteDocuments.parse(receipt);var after=SiteDocuments.parse((String)saved.get("after"));after.put("future",Map.of("changed",true));saved.put("after",SiteDocuments.text(after));SiteDocuments.write(path,SiteDocuments.text(saved));assertEquals(Outcome.Kind.BLOCKED,participant.settle(decision(1,Recipient.character(to))).kind());SiteDocuments.write(path,receipt);
        SiteDocuments.write(root.resolve("sites/"+id+".yml"),SiteDocuments.text(raw()));assertEquals(Outcome.Kind.BLOCKED,participant.settle(decision(1,Recipient.character(to))).kind());store.open();assertEquals(Outcome.Kind.BLOCKED,participant.settle(decision(1,Recipient.character(to))).kind());var newer=decision(2,Recipient.character(to));activate(newer);assertEquals(Outcome.Kind.BLOCKED,participant.settle(newer).kind());assertEquals(from,SiteOwnership.director(store.documents().get(id+".yml")));
    }
    @Test public void pendingEstateTamperCannotRelabelKindChangePathDirectorOrUnrelatedHistory()throws Exception{
        var participant=new SiteEstates(repository);assertEquals(Outcome.Kind.DONE,participant.settle(decision(1,Recipient.character(to))).kind());Path path=store.files("ownership/journals").getFirst();var original=SiteDocuments.parse(Files.readString(path));String current=Files.readString(root.resolve("sites/"+id+".yml"));
        for(String fault:List.of("kind","path","director","workers")){
            var journal=SiteDocuments.copy(original);var after=SiteDocuments.parse((String)journal.get("after"));switch(fault){case "kind"->journal.put("kind","migration");case "path"->journal.put("file","../outside.yml");case "director"->after.put("director",from.characterId().toString());case "workers"->after.put("workers",Map.of());}journal.put("after",SiteDocuments.text(after));journal.put("done",false);assertThrows(IOException.class,()->store.publish(path,journal));assertEquals(current,Files.readString(root.resolve("sites/"+id+".yml")));
        }
    }

    @Test public void loadedHandoverFlushesBufferedTalliesWithoutResettingDirectorHistoryOrRecipientProgress()throws Exception{
        Files.delete(root.resolve("sites/"+id+".yml"));var plugin=spy(MockBukkit.createMockPlugin());doReturn(root.toFile()).when(plugin).getDataFolder();repository=new SiteRepository(plugin);repository.loadAll();var site=new net.tfminecraft.archaeo.model.Site();site.setId(id);site.setSerial(1);site.setInterest(net.tfminecraft.archaeo.model.InterestLevel.LOW);site.setWorldName("world");site.setCreatedAt(Instant.EPOCH);site.setDirector(from.characterId());site.getActorRefs().put(from.characterId(),from);site.getActorRefs().put(to.characterId(),to);site.grantExcavator(from.characterId());site.grantExcavator(to.characterId());site.setStatus(net.tfminecraft.archaeo.model.SiteStatus.ESTABLISHED);site.worker(from.characterId()).setRole(net.tfminecraft.archaeo.model.SiteRole.DIRECTOR);site.worker(to.characterId()).setBlocksRemoved(17);repository.save(site);site.worker(from.characterId()).setBlocksRemoved(11);repository.touch(site);var participant=new SiteEstates(repository);assertEquals(Outcome.Kind.DONE,participant.settle(decision(1,Recipient.character(to))).kind());assertEquals(to.characterId(),site.getDirector());assertEquals(11,site.workerRecord(from.characterId()).getBlocksRemoved());assertEquals(17,site.workerRecord(to.characterId()).getBlocksRemoved());assertEquals(net.tfminecraft.archaeo.model.SiteRole.DIRECTOR,site.workerRecord(from.characterId()).getRole());assertEquals(net.tfminecraft.archaeo.model.SiteRole.defaultRole(),site.roleOf(from.characterId()));repository.loadAll();assertEquals(11,repository.findById(id).orElseThrow().workerRecord(from.characterId()).getBlocksRemoved());
    }

    @Test public void untouchedObsoleteIntentArchivesWithoutMovedIdThenNewRecipientReceivesSite()throws Exception{
        var participant=new SiteEstates(repository);try(var writes=mockStatic(SiteDocuments.class,CALLS_REAL_METHODS)){writes.when(()->SiteDocuments.write(any(Path.class),anyString())).thenAnswer(call->{call.callRealMethod();if(((Path)call.getArgument(0)).toString().contains("ownership/journals"))throw new IOException("crash after untouched intent");return null;});assertEquals(Outcome.Kind.RETRY,participant.settle(decision(1,Recipient.character(to))).kind());}
        String original=Files.readString(root.resolve("sites/"+id+".yml"));Path old=store.files("ownership/journals").getFirst();String intent=Files.readString(old);var nextOwner=new CharacterRef(UUID.randomUUID(),UUID.randomUUID());var newer=decision(2,Recipient.character(nextOwner));activate(newer);store.open();assertTrue(store.held(id+".yml"));var done=(Outcome.Done)participant.settle(newer);assertEquals(List.of(id.toString()),done.movedIds());assertEquals(nextOwner,SiteOwnership.director(store.documents().get(id+".yml")));assertEquals(intent,Files.readString(root.resolve("ownership/superseded/"+old.getFileName())));assertFalse(Files.exists(old));assertEquals(1,store.files("ownership/journals").size());assertEquals(original,SiteDocuments.parse(intent).get("before"));assertEquals(done,participant.settle(newer));
    }
    @Test public void completedZeroCannotAbsorbALateSourceOnSameRevisionButNewRevisionMovesIt()throws Exception{
        Files.delete(root.resolve("sites/"+id+".yml"));store.open();var participant=new SiteEstates(repository);var current=decision(1,Recipient.character(to));assertEquals(Map.of("sites",0),((Outcome.Done)participant.settle(current)).counts());SiteDocuments.write(root.resolve("sites/"+id+".yml"),SiteDocuments.text(raw()));store.open();assertEquals(Outcome.Kind.BLOCKED,participant.settle(current).kind());assertEquals(from,SiteOwnership.director(store.documents().get(id+".yml")));var newer=decision(2,Recipient.character(to));activate(newer);assertEquals(List.of(id.toString()),((Outcome.Done)participant.settle(newer)).movedIds());store.open();assertEquals(Outcome.Kind.DONE,participant.settle(newer).kind());
    }
    @Test public void frozenCompletionRetainsOriginalOwnershipButRejectsLateResolvedSourcesUntilNewRevision()throws Exception{
        var participant=new SiteEstates(repository);var frozen=decision(1,Recipient.FROZEN);activate(frozen);assertEquals(Outcome.Kind.DONE,participant.settle(frozen).kind());store.open();assertEquals(Outcome.Kind.DONE,participant.settle(frozen).kind());UUID late=UUID.randomUUID();var added=raw();added.put("id",late.toString());SiteDocuments.write(root.resolve("sites/"+late+".yml"),SiteDocuments.text(added));store.open();assertEquals(Outcome.Kind.BLOCKED,participant.settle(frozen).kind());var newer=decision(2,Recipient.character(to));activate(newer);assertEquals(Set.of(id.toString(),late.toString()),new HashSet<>(((Outcome.Done)participant.settle(newer)).movedIds()));
    }
    @Test public void completionFullDecisionCountIdsAndRetainedOwnershipCorruptionCannotAcknowledge()throws Exception{
        var participant=new SiteEstates(repository);var frozen=decision(1,Recipient.FROZEN);activate(frozen);assertEquals(Outcome.Kind.DONE,participant.settle(frozen).kind());Path path=root.resolve("ownership/completions/"+death+"/1.yml");String original=Files.readString(path);var stamp=SiteDocuments.parse(original);for(String fault:List.of("revision","decision","counts","moved","retained","bad-name")){var changed=SiteDocuments.copy(stamp);switch(fault){case "revision"->changed.put("revision",1.5);case "decision"->changed.put("decision",((String)changed.get("decision")).replace("property=Frozen[]","property=Waiting[]"));case "counts"->changed.put("counts",Map.of("sites",1));case "moved"->changed.put("moved",List.of(UUID.randomUUID().toString()));case "retained"->changed.put("retained",Map.of());case "bad-name"->changed.put("retained",Map.of("bad.yml",CharacterActors.ref(from)));}SiteDocuments.write(path,SiteDocuments.text(changed));assertEquals(Outcome.Kind.BLOCKED,participant.settle(frozen).kind());assertEquals(from,SiteOwnership.director(store.documents().get(id+".yml")));}SiteDocuments.write(path,original);assertEquals(Outcome.Kind.DONE,participant.settle(frozen).kind());
    }

    @Test public void completedZeroBlocksValidPendingReplayOnStartupBeforeAnyOwnershipPublication()throws Exception{
        Files.delete(root.resolve("sites/"+id+".yml"));store.open();var participant=new SiteEstates(repository);var current=decision(1,Recipient.character(to));assertEquals(Outcome.Kind.DONE,participant.settle(current).kind());SiteDocuments.write(root.resolve("sites/"+id+".yml"),SiteDocuments.text(raw()));store.open();String original=store.before(id+".yml");Map<String,Object> header=new LinkedHashMap<>();header.put("death",death.toString());header.put("revision",1);header.put("decision",current.toString());header.put("from",CharacterActors.ref(from));header.put("to",CharacterActors.ref(to));assertThrows(IOException.class,()->store.commit(id+".yml",original,SiteOwnership.transfer(raw(),to),Map.of("kind","estate","estate",header)));assertEquals(original,Files.readString(root.resolve("sites/"+id+".yml")));store.open();assertTrue(store.held(id+".yml"));assertEquals(original,Files.readString(root.resolve("sites/"+id+".yml")));assertEquals(Outcome.Kind.BLOCKED,participant.settle(current).kind());var newer=decision(2,Recipient.character(to));activate(newer);assertEquals(List.of(id.toString()),((Outcome.Done)participant.settle(newer)).movedIds());
    }

    @Test public void corruptHistoricalCompletionOrLaterReceiptBlocksPendingRevisionBeforeSettleOrStartupEffects()throws Exception{
        var participant=new SiteEstates(repository);var frozen=decision(1,Recipient.FROZEN);activate(frozen);assertEquals(Outcome.Kind.DONE,participant.settle(frozen).kind());var newer=decision(2,Recipient.character(to));activate(newer);
        try(var writes=mockStatic(SiteDocuments.class,CALLS_REAL_METHODS)){writes.when(()->SiteDocuments.write(any(Path.class),anyString())).thenAnswer(call->{call.callRealMethod();if(((Path)call.getArgument(0)).toString().contains("ownership/journals"))throw new IOException("crash after valid pending intent");return null;});assertEquals(Outcome.Kind.RETRY,participant.settle(newer).kind());}
        Path pending=store.files("ownership/journals").getFirst(),stamp=root.resolve("ownership/completions/"+death+"/1.yml");String intent=Files.readString(pending),source=Files.readString(root.resolve("sites/"+id+".yml")),completion=Files.readString(stamp);var bad=SiteDocuments.parse(completion);bad.put("counts",Map.of("sites",1));SiteDocuments.write(stamp,SiteDocuments.text(bad));assertEquals(Outcome.Kind.BLOCKED,participant.settle(newer).kind());assertEquals(source,Files.readString(root.resolve("sites/"+id+".yml")));assertEquals(intent,Files.readString(pending));store.open();assertEquals(source,Files.readString(root.resolve("sites/"+id+".yml")));assertEquals(intent,Files.readString(pending));SiteDocuments.write(stamp,completion);
        Path later=root.resolve("ownership/journals/zz-later.yml");var corrupt=SiteDocuments.parse(intent);corrupt.put("id","zz-later");var after=SiteDocuments.parse((String)corrupt.get("after"));after.put("future",Map.of("lost",true));corrupt.put("after",SiteDocuments.text(after));SiteDocuments.write(later,SiteDocuments.text(corrupt));assertEquals(Outcome.Kind.BLOCKED,participant.settle(newer).kind());assertEquals(source,Files.readString(root.resolve("sites/"+id+".yml")));assertEquals(intent,Files.readString(pending));store.open();assertEquals(source,Files.readString(root.resolve("sites/"+id+".yml")));assertEquals(intent,Files.readString(pending));Files.delete(later);store.open();assertEquals(Outcome.Kind.DONE,participant.settle(newer).kind());
    }

    @Test public void changedHistoricalCompletionDecisionCannotDisagreeWithItsRevisionReceipts()throws Exception{
        var participant=new SiteEstates(repository);var original=decision(1,Recipient.character(to));assertEquals(Outcome.Kind.DONE,participant.settle(original).kind());Path stamp=root.resolve("ownership/completions/"+death+"/1.yml");var changed=SiteDocuments.parse(Files.readString(stamp));var wrong=new CharacterRef(UUID.randomUUID(),UUID.randomUUID());changed.put("to",CharacterActors.ref(wrong));changed.put("property",Recipient.character(wrong).toString());changed.put("decision",decision(1,Recipient.character(wrong)).toString());SiteDocuments.write(stamp,SiteDocuments.text(changed));var newer=decision(2,Recipient.WAITING);activate(newer);String source=Files.readString(root.resolve("sites/"+id+".yml"));assertEquals(Outcome.Kind.BLOCKED,participant.settle(newer).kind());assertEquals(source,Files.readString(root.resolve("sites/"+id+".yml")));assertFalse(Files.exists(root.resolve("ownership/completions/"+death+"/2.yml")));
    }
}
